import type { IncomingMessage, ServerResponse } from "node:http";

import { CreatePile, ListPiles } from "../../storage/index.js";
import { StorageError } from "../../storage/errors.js";
import { ReadJsonBody, SendJson } from "../http.js";
import type { RouteContext } from "./context.js";

function ParseCreatePileBody(body: unknown): string
{
  if (body === null || typeof body !== "object")
  {
    throw new StorageError("invalid_request", "request body must be a JSON object");
  }

  const pile = (body as { pile?: unknown }).pile;

  if (typeof pile !== "string" || pile.trim().length === 0)
  {
    throw new StorageError("invalid_request", "pile name is required");
  }

  return pile;
}

export async function HandleListPiles(context: RouteContext, response: ServerResponse): Promise<void>
{
  const piles = await ListPiles(context.agentManager.storagePaths);
  SendJson(response, 200, { piles });
}

export async function HandleCreatePile(
  context: RouteContext,
  request: IncomingMessage,
  response: ServerResponse,
): Promise<void>
{
  const body = await ReadJsonBody(request);
  const pile = ParseCreatePileBody(body);
  const summary = await CreatePile(context.agentManager.storagePaths, pile);
  SendJson(response, 201, summary);
}

import type { IncomingMessage, ServerResponse } from "node:http";

import { RelativizeAbsolutePath } from "../../agui/sanitizer.js";
import type { ModelReference } from "../../shared/types.js";
import { ListSessionManifests, ReadManifest } from "../../storage/manifests.js";
import { StorageError } from "../../storage/errors.js";
import { ReadJsonBody, SendJson } from "../http.js";
import { BuildChatWebSocketUrl } from "../websockets.js";
import type { RouteContext } from "./context.js";

function ParseModelReference(value: unknown): ModelReference
{
  if (value === null || typeof value !== "object")
  {
    throw new StorageError("invalid_request", "model must be an object");
  }

  const provider = (value as { provider?: unknown }).provider;
  const id = (value as { id?: unknown }).id;

  if (typeof provider !== "string" || provider.trim().length === 0)
  {
    throw new StorageError("invalid_request", "model.provider is required");
  }

  if (typeof id !== "string" || id.trim().length === 0)
  {
    throw new StorageError("invalid_request", "model.id is required");
  }

  return {
    provider,
    id,
  };
}

function ParseCreateSessionBody(body: unknown): { rootDirectory: string; model: ModelReference }
{
  if (body === null || typeof body !== "object")
  {
    throw new StorageError("invalid_request", "request body must be a JSON object");
  }

  const rootDirectory = (body as { rootDirectory?: unknown }).rootDirectory;

  if (typeof rootDirectory !== "string" || rootDirectory.trim().length === 0)
  {
    throw new StorageError("invalid_request", "rootDirectory is required");
  }

  const model = ParseModelReference((body as { model?: unknown }).model);

  return {
    rootDirectory,
    model,
  };
}

export async function HandleListSessions(
  context: RouteContext,
  pile: string,
  response: ServerResponse,
): Promise<void>
{
  const sessions = await ListSessionManifests(context.agentManager.storagePaths, pile);
  SendJson(response, 200, { sessions });
}

export async function HandleGetSession(
  context: RouteContext,
  pile: string,
  sessionId: string,
  response: ServerResponse,
): Promise<void>
{
  const manifest = await ReadManifest(context.agentManager.storagePaths, pile, sessionId);
  SendJson(response, 200, { manifest });
}

export async function HandleCreateSession(
  context: RouteContext,
  pile: string,
  request: IncomingMessage,
  response: ServerResponse,
): Promise<void>
{
  const body = await ReadJsonBody(request);
  const input = ParseCreateSessionBody(body);
  const result = await context.agentManager.createBlankSession(
    pile,
    input.rootDirectory,
    input.model,
  );
  const relativeRoot = RelativizeAbsolutePath(
    result.shell.provisionalSession.rootDirectory,
    context.config.repoRoot,
  );

  SendJson(response, 201, {
    sessionId: result.shell.sessionId,
    provisionalSession: {
      rootDirectory: relativeRoot,
      model: result.shell.provisionalSession.model,
    },
    webSocketUrl: BuildChatWebSocketUrl({
      pile: result.key.pile,
      sessionId: result.key.sessionId,
    }),
  });
}

export interface BuildChatWebSocketUrlInput
{
  pile: string;
  sessionId: string;
  clientId?: string;
  after?: number;
}

export function BuildChatWebSocketUrl(input: BuildChatWebSocketUrlInput): string
{
  const params = new URLSearchParams();
  params.set("p", input.pile);
  params.set("session", input.sessionId);

  if (input.clientId !== undefined && input.clientId.length > 0)
  {
    params.set("client", input.clientId);
  }

  if (input.after !== undefined)
  {
    params.set("after", String(input.after));
  }

  return `/ws/chat?${params.toString()}`;
}

import { mkdirSync } from "node:fs";

import { AgentManager } from "../../../src/agents/manager.js";
import type { SheafChatConfig } from "../../../src/server/config.js";
import { CreateSheafChatServer } from "../../../src/server/server.js";
import { CreateStoragePaths } from "../../../src/storage/paths.js";
import { CreateTestModelBundle } from "../../agents/lifecycle/helpers.js";
import { BuildTestConfig, WithFakeRepoAsync } from "../../agents/modelRegistry/helpers.js";

export interface TestServerHandle
{
  baseUrl: string;
  config: SheafChatConfig;
  agentManager: AgentManager;
  close: () => Promise<void>;
}

export async function StartTestServer(repoRoot: string): Promise<TestServerHandle>
{
  mkdirSync(repoRoot, { recursive: true });
  mkdirSync(`${repoRoot}/projects/demo`, { recursive: true });

  const config = BuildTestConfig(repoRoot, {
    openAiApiKey: "test-key",
  });
  const storagePaths = CreateStoragePaths(repoRoot);
  const modelBundle = CreateTestModelBundle();
  const agentManager = await AgentManager.Create({
    config,
    storagePaths,
    modelBundle,
  });
  const server = CreateSheafChatServer({
    config,
    bindHost: "127.0.0.1",
    bindPort: 0,
    agentManager,
  });
  const port = await server.listen();
  const baseUrl = `http://127.0.0.1:${port}`;

  return {
    baseUrl,
    config,
    agentManager,
    close: async () =>
    {
      await server.close();
      await agentManager.dispose();
    },
  };
}

export async function WithTestServer(
  callback: (handle: TestServerHandle) => Promise<void>,
): Promise<void>
{
  await WithFakeRepoAsync(async (repoRoot) =>
  {
    const handle = await StartTestServer(repoRoot);

    try
    {
      await callback(handle);
    }
    finally
    {
      await handle.close();
    }
  });
}

export async function RequestJson(
  baseUrl: string,
  method: string,
  route: string,
  body?: unknown,
): Promise<{ status: number; body: unknown }>
{
  const response = await fetch(`${baseUrl}${route}`, {
    method,
    headers: body === undefined ? undefined : { "content-type": "application/json" },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
