import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import test from "node:test";
import vm from "node:vm";
import { fileURLToPath } from "node:url";

const x_testDirectory = path.dirname(fileURLToPath(import.meta.url));
const sheafChatJsPath = path.resolve(x_testDirectory, "../../src/ui/sheaf-chat.js");

function LoadSheafChatApp(): {
  parseRoute: (hash: string) => { screen: string; pile?: string; sessionId?: string };
  buildWebSocketUrl: (pile: string, sessionId: string, after?: number) => string;
  createEnvelope: (
    kind: string,
    pile: string,
    sessionId: string,
    payload: unknown,
  ) => Record<string, unknown>;
  isTouchLayout: () => boolean;
}
{
  const source = fs.readFileSync(sheafChatJsPath, "utf8");
  const context: Record<string, unknown> = {
    console,
    setTimeout,
    clearTimeout,
    localStorage: {
      getItem: () => null,
      setItem: () => undefined,
    },
    crypto: {
      randomUUID: () => "test-uuid",
    },
    document: {
      readyState: "complete",
      addEventListener: () => undefined,
      getElementById: () => null,
    },
    location: {
      protocol: "http:",
      host: "127.0.0.1:9004",
      hash: "#/",
    },
    window: null as unknown,
  };
  context.window = context;
  context.globalThis = context;
  vm.createContext(context);
  vm.runInContext(source, context);
  const app = context.SheafChatApp as { _test: {
    parseRoute: () => { screen: string };
    buildWebSocketUrl: (pile: string, sessionId: string, after?: number) => string;
    createEnvelope: (
      kind: string,
      pile: string,
      sessionId: string,
      payload: unknown,
    ) => Record<string, unknown>;
    isTouchLayout: () => boolean;
  } };
  return app._test as {
    parseRoute: (hash: string) => { screen: string; pile?: string; sessionId?: string };
    buildWebSocketUrl: (pile: string, sessionId: string, after?: number) => string;
    createEnvelope: (
      kind: string,
      pile: string,
      sessionId: string,
      payload: unknown,
    ) => Record<string, unknown>;
    isTouchLayout: () => boolean;
  };
}

test("router parses piles, sessions, and chat routes", () =>
{
  const { parseRoute } = LoadSheafChatApp();

  const originalHash = (globalThis as { location?: { hash: string } }).location?.hash;
  const location = { hash: "#/" };
  (globalThis as { location: { hash: string } }).location = location;

  try
  {
    location.hash = "#/";
    assert.deepEqual(parseRoute(), { screen: "piles" });

    location.hash = "#/piles/demo";
    assert.deepEqual(parseRoute(), { screen: "sessions", pile: "demo" });

    location.hash = "#/piles/demo/sessions/sess-1";
    assert.deepEqual(parseRoute(), {
      screen: "chat",
      pile: "demo",
      sessionId: "sess-1",
    });
  }
  finally
  {
    if (originalHash !== undefined)
    {
      (globalThis as { location: { hash: string } }).location.hash = originalHash;
    }
  }
});

test("buildWebSocketUrl includes reconnect after sequence", () =>
{
  const { buildWebSocketUrl } = LoadSheafChatApp();
  const url = buildWebSocketUrl("default", "sess-1", 42);
  assert.match(url, /^ws:\/\/127\.0\.0\.1:9004\/ws\/chat\?/);
  assert.match(url, /p=default/);
  assert.match(url, /session=sess-1/);
  assert.match(url, /after=42/);
  assert.match(url, /client=/);
});

test("createEnvelope builds protocol frames", () =>
{
  const { createEnvelope } = LoadSheafChatApp();
  const envelope = createEnvelope("client.user_message", "default", "sess-1", {
    text: "hello",
  });
  assert.equal(envelope.v, 1);
  assert.equal(envelope.kind, "client.user_message");
  assert.equal(envelope.pile, "default");
  assert.equal(envelope.sessionId, "sess-1");
  assert.deepEqual(envelope.payload, { text: "hello" });
});

